import{_ as o,a0 as r,w as l,s as d,I as e,x as n,a1 as t,A as i,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"利用 DNS SRV 記錄為 Postfix 提供負載平衡 | LCTT x X-CMD","titleTemplate":false,"description":"利用 DNS SRV 記錄為 Postfix 提供負載平衡 | LCTT (202312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"利用 DNS SRV 記錄為 Postfix 提供負載平衡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"利用 DNS SRV 記錄為 Postfix 提供負載平衡 | LCTT (202312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202312/20230616 Using Postfix DNS SRV record resolution feature","title":"利用 DNS SRV 記錄為 Postfix 提供負載平衡","tag":"202312","desc":""},"relativePath":"202312/20230616 Using Postfix DNS SRV record resolution feature.md","filePath":"[post].md"}'),c={name:"202312/20230616 Using Postfix DNS SRV record resolution feature.md"};function h(u,s,f,m,g,b){const a=r("Link");return l(),d("div",null,[s[24]||(s[24]=e("h1",{id:"利用-dns-srv-記錄為-postfix-提供負載平衡",tabindex:"-1"},[n("利用 DNS SRV 記錄為 Postfix 提供負載平衡 "),e("a",{class:"header-anchor",href:"#利用-dns-srv-記錄為-postfix-提供負載平衡","aria-label":"Permalink to “利用 DNS SRV 記錄為 Postfix 提供負載平衡”"},"​")],-1)),s[25]||(s[25]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202312/15/173522hpze31p331ppljrj.jpg",alt:""})],-1)),e("p",null,[s[1]||(s[1]=n("2011 年 3 月，蘋果公司提出 ",-1)),t(a,{href:"https://www.ietf.org/rfc/rfc6186.txt"},{default:i(()=>[...s[0]||(s[0]=[n("RFC 6186",-1)])]),_:1}),s[2]||(s[2]=n("，描述瞭如何利用域名系統服務（DNS SRV）記錄來查找電子郵件的提交以及訪問服務。現在 Postfix 從 3.8.0 版本開始支持 RFC 中提出的設計。這個新增功能讓你可以使用 DNS SRV 記錄進行負載分配和自動配置。",-1))]),s[26]||(s[26]=e("h3",{id:"dns-srv-記錄的形態",tabindex:"-1"},[n("DNS SRV 記錄的形態 "),e("a",{class:"header-anchor",href:"#dns-srv-記錄的形態","aria-label":"Permalink to “DNS SRV 記錄的形態”"},"​")],-1)),e("p",null,[s[4]||(s[4]=n("DNS SRV 記錄定義在 ",-1)),t(a,{href:"https://www.ietf.org/rfc/rfc2782.txt"},{default:i(()=>[...s[3]||(s[3]=[n("RFC 2782",-1)])]),_:1}),s[5]||(s[5]=n(" 中，它指定在區域文件中，並且包含了服務名稱、傳輸協議規範、優先級、權重、端口，以及提供該服務的主機。",-1))]),s[27]||(s[27]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>_submission._tcp    SRV 5 10 50 bruce.my-domain.com.</span></span></code></pre></div><div class="table-wrap"><table><thead><tr><th>字段</th><th>值</th><th>意義</th></tr></thead><tbody><tr><td>服務名稱</td><td><code>submission</code></td><td>服務名為 submission</td></tr><tr><td>傳輸協議規範</td><td><code>tcp</code></td><td>本服務使用 TCP 協議</td></tr><tr><td>優先級</td><td><code>5</code></td><td>服務器優先級設為 5（數值越小，優先級越高）</td></tr><tr><td>權重</td><td><code>10</code></td><td>服務器應承擔的負載部分</td></tr><tr><td>端口</td><td><code>50</code></td><td>服務器監聽連接的端口</td></tr><tr><td>目標</td><td><code> bruce.my-domain.com.</code></td><td>提供此服務的服務器名稱</td></tr></tbody></table></div><p><em>記錄解釋</em></p><h3 id="服務器選擇算法" tabindex="-1">服務器選擇算法 <a class="header-anchor" href="#服務器選擇算法" aria-label="Permalink to “服務器選擇算法”">​</a></h3>',4)),e("p",null,[s[7]||(s[7]=n("客户端應該按照 ",-1)),t(a,{href:"https://www.ietf.org/rfc/rfc2782.txt"},{default:i(()=>[...s[6]||(s[6]=[n("RFC 2782",-1)])]),_:1}),s[8]||(s[8]=n(" 中描述的方式解析 SRV 記錄。這意味着，首先嚐試聯繫擁有最高優先級（最小的優先級數字）的服務器。如果該服務器無回應，那麼重試聯繫擁有同樣或者更低優先級的下一台服務器。當有多台服務器擁有同樣優先級的時候，應隨機選擇其中一台，但是必須確保選擇記錄的概率符合下列公式：",-1))]),s[28]||(s[28]=p(`<p><img src="https://fedoramagazine.org/wp-content/uploads/2023/06/probability_equation.png" alt=""></p><p>其中 <code>i</code> 是 SRV 記錄的標識，<code>k</code> 是具有相同優先級的 SRV 記錄的數量。</p><p>在現實中，這意味着如果你有兩台服務器，其中一台的處理能力是另一台的三倍，那麼你應該給第一台服務器的權重賦於另一台三倍的值。這樣就能保證更強大的服務器會接收到大約 75% 的客户端請求，而另一台接收大約 25% 的請求。</p><p>這些原則使得 SRV 記錄能夠同時作為客户端自動配置及在服務器之間分配工作負載的工具。</p><p>看看以下這個記錄的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>_submission._tcp     SRV 0 0 2525 server-one</span></span>
<span class="line"><span>_submission._tcp     SRV 1 75 2625 server-two</span></span>
<span class="line"><span>_submission._tcp     SRV 1 25 2625 server-three</span></span></code></pre></div><p>這裏 <code>server-one</code> 總是會被首選來進行聯繫。如果 <code>server-one</code> 無回應，客户端就會將剩下優先級為 1 的兩個記錄順序打亂，生成一個從 0 到 100 的隨機數，如果第一條記錄的運行總和大於或者等於這個隨機數，它就會嘗試去聯繫這個記錄。否則，客户端會倒序聯繫所有服務器。注意，客户端會向它優先成功連接的服務器發送請求。</p><h3 id="示例配置" tabindex="-1">示例配置 <a class="header-anchor" href="#示例配置" aria-label="Permalink to “示例配置”">​</a></h3><p>請考慮以下這種情況。你想為大量的電腦配置 Postfix，使其通過公司的郵件服務器利用 SRV 記錄轉發外部電郵。為了達到這個目標，你需要在每台電腦的 Postfix 中配置 <code>relayhost</code> 參數，即郵件用户代理（MUA）。如果將 <code>relayhost</code> 參數的值設置為 <code>$mydomain</code>，你的機器將開始為你的域名查找 MX 記錄，並嘗試按照它們的優先級順序發送郵件。這種方法雖然有效，但是可能會遇到負載平衡問題。Postfix 會使用優先級最高的服務器，直到其變為無響應才會聯繫其他備用服務器。此外，如果你在環境中使用了動態分配的端口，你無法指明哪個端口正在被特定的服務器使用。使用 SRV 記錄，你可以應對這些挑戰，並在需要改變服務器端口的時候維持服務器的平滑運行。</p><h4 id="區域文件" tabindex="-1">區域文件 <a class="header-anchor" href="#區域文件" aria-label="Permalink to “區域文件”">​</a></h4><p>為了使得 DNS 服務器提供信息給客户端，可以參考以下使用服務器 <code>server-one</code>、<code>server-two</code>、<code>server-three</code> 作為中繼，並把服務器 <code>server-four</code> 配置為接收測試郵件的區域文件示例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$TTL  3600</span></span>
<span class="line"><span>@       IN SOA  example-domain.com. root.example-domain.com. (</span></span>
<span class="line"><span>                1571655122 ; 區域文件的序列號</span></span>
<span class="line"><span>                1200       ; 刷新時間</span></span>
<span class="line"><span>                180        ; 發生問題時的重試時間</span></span>
<span class="line"><span>                1209600    ; 過期時間</span></span>
<span class="line"><span>                10800 )    ; 查詢失敗時的最大緩存時間</span></span>
<span class="line"><span>;</span></span>
<span class="line"><span>        IN NS   ns1</span></span>
<span class="line"><span>        IN A    192.168.2.0</span></span>
<span class="line"><span>;</span></span>
<span class="line"><span>ns1     IN A    192.168.2.2</span></span>
<span class="line"><span>server-one           IN A   192.168.2.4</span></span>
<span class="line"><span>server-two           IN A   192.168.2.5</span></span>
<span class="line"><span>server-three         IN A   192.168.2.6</span></span>
<span class="line"><span>server-four          IN A   192.168.2.7</span></span>
<span class="line"><span>_submission._tcp     SRV 0 0 2525  server-one</span></span>
<span class="line"><span>_submission._tcp     SRV 1 50 2625 server-two</span></span>
<span class="line"><span>_submission._tcp     SRV 1 50 2625 server-three</span></span>
<span class="line"><span>@ MX 0 server-four</span></span></code></pre></div><h4 id="postfix-mua-配置" tabindex="-1">Postfix MUA 配置 <a class="header-anchor" href="#postfix-mua-配置" aria-label="Permalink to “Postfix MUA 配置”">​</a></h4><p>設置客户端機器去查找 SRV 記錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>use_srv_lookup = submission</span></span>
<span class="line"><span>relayhost = example-domain.com:submission</span></span></code></pre></div><p>通過這個配置，你的客户端機器上的 Postfix 實例會聯絡到 <code>example-domain</code> 的 DNS 服務器，然後獲取郵件提交的 SRV 記錄。在這個例子中，<code>server-one</code> 有最高的優先級，Postfix 會先試圖連接它。然後，Postfix 隨機的選擇剩下的兩個服務器其中一個去嘗試連接。這個配置確保了大約有 50% 的機會會優先聯繫到服務器一。注意，SRV 記錄的權重值並不等同於百分比。你也可以用 1 和 1 這樣的值達到同樣的目標。</p><p>同時，Postfix 也知道 <code>server-one</code> 在監聽 2525 端口，而 <code>server-two</code> 在監聽 2625 端口。如果你正在緩存檢索到的 DNS 記錄，並且你動態改變 SRV 記錄，那麼設置一個低的生存時間（TTL）對你的記錄是很重要的。</p><h4 id="整套設置" tabindex="-1">整套設置 <a class="header-anchor" href="#整套設置" aria-label="Permalink to “整套設置”">​</a></h4><p><img src="https://fedoramagazine.org/wp-content/uploads/2023/06/srv_article.png" alt=""></p><p>你可以通過下面的方式嘗試這個配置，包含 podman 和在此處提供的 compose 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://github.com/TomasKorbar/srv_article</span></span>
<span class="line"><span>$ cd srv_article/environment</span></span>
<span class="line"><span>$ podman-compose up</span></span>
<span class="line"><span>$ podman exec -it article_client /bin/bash</span></span>
<span class="line"><span>root@client # ./senddummy.sh</span></span>
<span class="line"><span>root@client # exit</span></span></code></pre></div><p>完成配置之後，你可以檢查日誌，查看郵件是否經過 <code>server-one</code> 並最終投遞到 <code>server-four</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman stop article_server1</span></span>
<span class="line"><span>$ podman exec -it article_client /bin/bash</span></span>
<span class="line"><span>root@client # ./senddummy.sh</span></span>
<span class="line"><span>root@client # ./senddummy.sh</span></span>
<span class="line"><span>root@client # ./senddummy.sh</span></span>
<span class="line"><span>root@client # ./senddummy.sh</span></span>
<span class="line"><span>root@client # ./senddummy.sh</span></span>
<span class="line"><span>root@client # ./senddummy.sh</span></span>
<span class="line"><span>root@client # exit</span></span></code></pre></div><p>現在 <code>server-one</code> 已經關閉了，這六封郵件將會由 <code>server-two</code> 或者 <code>server-three</code> 中轉發出去。</p><p>仔細看一下 Dockerfiles 以更深地理解這個配置。</p><p>通過執行：<code>$ podman-compose down</code> 完成示例的操作。</p><p><em>（題圖：DA/241079fe-58d6-4dc6-8801-f0fd19dfd64b）</em></p><hr>`,28)),e("p",null,[s[10]||(s[10]=n("via: ",-1)),t(a,{href:"https://fedoramagazine.org/using-postfix-dns-srv-record-resolution-feature/"},{default:i(()=>[...s[9]||(s[9]=[n("https://fedoramagazine.org/using-postfix-dns-srv-record-resolution-feature/",-1)])]),_:1})]),e("p",null,[s[15]||(s[15]=n("作者：",-1)),t(a,{href:"https://fedoramagazine.org/author/tkorbar/"},{default:i(()=>[...s[11]||(s[11]=[n("Tomáš Korbař",-1)])]),_:1}),s[16]||(s[16]=n(" 選題：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[12]||(s[12]=[n("lujun9972",-1)])]),_:1}),s[17]||(s[17]=n(" 譯者：",-1)),t(a,{href:"https://linux.cn/lctt/ChatGPT"},{default:i(()=>[...s[13]||(s[13]=[n("ChatGPT",-1)])]),_:1}),s[18]||(s[18]=n(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[14]||(s[14]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[21]||(s[21]=n("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[19]||(s[19]=[n("LCTT",-1)])]),_:1}),s[22]||(s[22]=n(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:i(()=>[...s[20]||(s[20]=[n("Linux中國",-1)])]),_:1}),s[23]||(s[23]=n(" 榮譽推出",-1))])])}const v=o(c,[["render",h]]);export{S as __pageData,v as default};
